using System;
using System.IO;
using System.IO.Compression;
using System.Linq;
namespace MfgLauncher
{
    public static class InstallationTests
    {
        static byte[] Pe(bool dll,byte value,bool x64){byte[] b=new byte[512];b[0]=0x4d;b[1]=0x5a;b[0x3c]=0x80;b[0x80]=0x50;b[0x81]=0x45;b[0x84]=x64?(byte)0x64:(byte)0x4c;b[0x85]=x64?(byte)0x86:(byte)1;b[0x96]=2;b[0x97]=dll?(byte)0x20:(byte)0;b[0x98]=0x0b;b[0x99]=x64?(byte)2:(byte)1;b[511]=value;return b;}
        static string Zip(string parent,string name,string entryName,byte[] bytes){string path=Path.Combine(parent,name+".zip");using(var zip=ZipFile.Open(path,ZipArchiveMode.Create))using(var e=zip.CreateEntry(entryName).Open())e.Write(bytes,0,bytes.Length);return path;}
        static bool Reject(Action action){try{action();return false;}catch(Exception ex){if(ex is IOException||ex is InvalidDataException||ex is InvalidOperationException||ex is UnauthorizedAccessException||ex is ArgumentException)return true;throw;}}
        static Game GameFixture(string path){Directory.CreateDirectory(path);string exe=Path.Combine(path,"Cyberpunk2077.exe");File.WriteAllBytes(exe,Pe(false,1,true));File.WriteAllBytes(Path.Combine(path,"sl.dlss_g.dll"),new byte[]{1});File.WriteAllBytes(Path.Combine(path,"nvngx_dlssg.dll"),new byte[]{1});var g=new Game{Name="Cyberpunk 2077",Root=path,Source="Custom",SelectedExe=exe};g.Executables.Add(exe);g.Files.AddRange(new[]{"Cyberpunk2077.exe","sl.dlss_g.dll","nvngx_dlssg.dll"});return g;}
        public static void Run(Action<bool,string> assert)
        {
            string parent=Path.Combine(Path.GetTempPath(),"MfgInstallerTests-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(parent);string previous=StateStore.DataDir;StateStore.DataDir=Path.Combine(parent,"state");
            try{
                string zip=Zip(parent,"valid","release/MFGUnlocker.dll",Pe(true,1,true));var package=PackageManager.Import(zip,"v1.7.0","fixture","sha256:"+Util.HashFile(zip));assert(package.DigestVerified&&Util.IsX64Pe(package.DllPath,true)&&package.Sha256==Util.HashFile(package.DllPath),"ZIP import verifies digest and x64 DLL");
                assert(Reject(()=>PackageManager.Import(zip,"v1.7.0","fixture",new string('0',64))),"Archive digest mismatch refused");
                string unsafeZip=Zip(parent,"traversal","../MFGUnlocker.dll",Pe(true,1,true));assert(Reject(()=>PackageManager.Import(unsafeZip,"v1.7.0","fixture",null)),"Archive traversal refused");string slashZip=Zip(parent,"backslash","..\\MFGUnlocker.dll",Pe(true,1,true));assert(Reject(()=>PackageManager.Import(slashZip,"v1.7.0","fixture",null)),"Backslash traversal refused");string x86=Zip(parent,"x86","MFGUnlocker.dll",Pe(true,1,false));assert(Reject(()=>PackageManager.Import(x86,"v1.7.0","fixture",null)),"x86 DLL import refused");string exeZip=Zip(parent,"exe","MFGUnlocker.dll",Pe(false,1,true));assert(Reject(()=>PackageManager.Import(exeZip,"v1.7.0","fixture",null)),"Executable renamed DLL refused");
                string duplicate=Path.Combine(parent,"duplicate.zip");using(var z=ZipFile.Open(duplicate,ZipArchiveMode.Create))foreach(string n in new[]{"MFGUnlocker.dll","MFGUNLOCKER.DLL"})using(var s=z.CreateEntry(n).Open()){byte[] b=Pe(true,1,true);s.Write(b,0,b.Length);}assert(Reject(()=>PackageManager.Import(duplicate,"v1.7.0","fixture",null)),"Duplicate ZIP entries refused");string link=Path.Combine(parent,"symlink.zip");using(var z=ZipFile.Open(link,ZipArchiveMode.Create)){var e=z.CreateEntry("MFGUnlocker.dll");e.ExternalAttributes=unchecked((int)0xa1ff0000);using(var s=e.Open()){byte[] b=Pe(true,1,true);s.Write(b,0,b.Length);}}assert(Reject(()=>PackageManager.Import(link,"v1.7.0","fixture",null)),"ZIP links refused");
                string html="<li><a href=\"/dashdogy/MFG-Unlocker/releases/download/v1.7.0/MFGUnlocker-v1.7.0.zip\">MFG</a><span>sha256:"+new string('a',64)+"</span></li>";var release=PackageManager.ParseAssets("v1.7.0",html);assert(release.Digest=="sha256:"+new string('a',64)&&release.AssetUrl.StartsWith("https://github.com/dashdogy/MFG-Unlocker/",StringComparison.Ordinal),"Official ZIP bound to per-asset digest");assert(Reject(()=>PackageManager.ParseAssets("v1.7.0",html.Replace("/dashdogy/","/attacker/"))),"Release URL outside upstream refused");
                var occupied=GameFixture(Path.Combine(parent,"occupied"));string dll=Path.Combine(occupied.Root,"xinput9_1_0.dll");File.WriteAllText(dll,"another mod");assert(Reject(()=>InstallService.Install(occupied,package,"xinput9_1_0.dll"))&&File.ReadAllText(dll)=="another mod","Occupied DLL never overwritten");
                var rollback=GameFixture(Path.Combine(parent,"install-rollback"));InstallService.Step=p=>{if(p=="install-dll-written")throw new IOException("fixture failure");};bool failed=Reject(()=>InstallService.Install(rollback,package,"xinput9_1_0.dll"));InstallService.Step=null;assert(failed&&!File.Exists(Path.Combine(rollback.Root,"xinput9_1_0.dll"))&&!File.Exists(Path.Combine(rollback.Root,InstallService.ReceiptName)),"Failed install rolls back exclusive DLL creation");
                var game=GameFixture(Path.Combine(parent,"game"));string settings=Path.Combine(game.Root,"RTXMFG-Universal.json");File.WriteAllText(settings,"keep settings");InstallService.Install(game,package,"xinput9_1_0.dll");var receipt=InstallService.ReadReceipt(game);assert(receipt!=null&&receipt.Sha256==package.Sha256&&File.Exists(receipt.DllPath),"Install writes valid ownership receipt");string selection=game.SelectedExe;game.SelectedExe=null;assert(InstallService.ReadReceipt(game)!=null,"Ownership readable independently of runtime selection");game.SelectedExe=selection;
                File.AppendAllText(receipt.DllPath,"modified");assert(Reject(()=>InstallService.Uninstall(game))&&File.Exists(receipt.DllPath)&&File.Exists(Path.Combine(game.Root,InstallService.ReceiptName)),"Uninstall preserves modified DLL");File.WriteAllBytes(receipt.DllPath,File.ReadAllBytes(package.DllPath));string zip2=Zip(parent,"valid2","MFGUnlocker.dll",Pe(true,2,true));var package2=PackageManager.Import(zip2,"v1.7.1","fixture","sha256:"+Util.HashFile(zip2));
                InstallService.Step=p=>{if(p=="update-dll-replaced")throw new IOException("fixture failure");};bool failedUpdate=Reject(()=>InstallService.Update(game,package2));InstallService.Step=null;assert(failedUpdate&&InstallService.ReadReceipt(game).Sha256==package.Sha256&&Util.HashFile(receipt.DllPath)==package.Sha256,"Update failure rolls back DLL to matching receipt");InstallService.Update(game,package2);receipt=InstallService.ReadReceipt(game);assert(receipt.Version=="v1.7.1"&&receipt.Sha256==package2.Sha256&&Directory.GetFiles(Path.Combine(StateStore.DataDir,"rollback"),"MFGUnlocker.dll",SearchOption.AllDirectories).Length>0,"Update replaces owned DLL and retains rollback data");
                InstallService.Step=p=>{if(p=="uninstall-dll-deleted")throw new IOException("fixture failure");};bool failedRemove=Reject(()=>InstallService.Uninstall(game));InstallService.Step=null;assert(failedRemove&&InstallService.ReadReceipt(game).Sha256==package2.Sha256,"Failed uninstall restores DLL");InstallService.Uninstall(game);assert(!File.Exists(receipt.DllPath)&&!File.Exists(Path.Combine(game.Root,InstallService.ReceiptName))&&File.ReadAllText(settings)=="keep settings","Uninstall preserves settings");
                var blocked=GameFixture(Path.Combine(parent,"blocked"));File.WriteAllText(Path.Combine(blocked.Root,"EasyAntiCheat_x64.dll"),"marker");assert(Reject(()=>InstallService.Install(blocked,package,"xinput9_1_0.dll")),"Fresh anti-cheat marker blocks stale scan install");var tampered=new PackageInfo{DllPath=package.DllPath,Version=package.Version,Sha256=new string('0',64),Source="fixture"};assert(Reject(()=>InstallService.Install(GameFixture(Path.Combine(parent,"tampered-package")),tampered,"xinput9_1_0.dll")),"Package tampering refused");
            }finally{InstallService.Step=null;StateStore.DataDir=previous;if(!Util.IsWithin(Path.GetTempPath(),parent))throw new IOException("Unsafe fixture cleanup path");Directory.Delete(parent,true);}
        }
    }
}

